    if (!found) throw new IOException("BAI bins/chunks cannot retrieve complete alignment at ordinal " + row.ordinal());
}

private void add(int n) throws IOException {
    if (bytes > maximum - n) throw new IOException("BAI grew beyond indexBytes");
    bytes += n;
}

@Override
public int read() throws IOException {
    int b = in.read();
    if (b >= 0) {
        add(1);
        digest.update((byte)b);
    }
    return b;
}

@Override
public int read(byte[] b, int off, int len) throws IOException {
