    crc.update(data, 0, written);
    if (crc.getValue() != Integer.toUnsignedLong(i32(tail, 0))) throw new IOException("BGZF CRC differs");
    blockAddress = nextAddress;
    nextAddress = Math.addExact(nextAddress, size);
    if (nextAddress >= (1L << 48)) throw new IOException("BGZF compressed address exceeds the48-bit index range");
    observer.block(blockAddress, size, written);
    if (written == 0) {
        if (size != 28 || raw.read() != -1) throw new IOException("Nonterminal or invalid empty BGZF member");
        ended = true;
        return false;
    }
    if (decoded > maximum - written) throw new IOException("Decoded BAM bytes exceed the declared limit");
    decoded += written;
    block = Arrays.copyOf(data, written);
    at = 0;
    return true;
}

@Override
public int read() throws IOException {
    if (at == block.length && !next()) return -1;
