    java.util.Objects.checkFromIndexSize(off, len, b.length);
    if (len == 0) return 0;
    if (at == block.length && !next()) return -1;
    int n = Math.min(len, block.length - at);
    System.arraycopy(block, at, b, off, n);
    at += n;
    return n;
}

long virtualOffset() {
    return at == block.length ? nextAddress << 16 : (blockAddress << 16) | at;
}

