private static void aux(byte[] raw, int at) throws IOException {
    /*missing*/ tags = new HashSet<Integer>();
    while (at < raw.length) {
        if (raw.length - at < 3) throw new IOException("Truncated auxiliary tag");
        int a = raw[at++] & 255;
        int b = raw[at++] & 255;
        int type = raw[at++] & 255;
        if (!((a >= 'A' && a <= 'Z') || (a >= 'a' && a <= 'z')) || !Character.isLetterOrDigit((char)b) || !tags.add(a * 256 + b)) throw new IOException("Invalid or repeated auxiliary tag");
        if (a == 'C' && b == 'G') throw new IOException("Long-CIGAR CG semantics require a separate profile");
        int width = switch (type) {
        case 'A', 'c', 'C' -> yield 1;
        case 's', 'S' -> yield 2;
        case 'i', 'I', 'f' -> yield 4;
        default -> yield 0;
        };
        if (width > 0) {
            if (at + width > raw.length) throw new IOException("Truncated numeric auxiliary field");
            at += width;
        } else if (type == 'Z' || type == 'H') {
            int start = at;
            while (at < raw.length && raw[at] != 0) {
                if (type == 'H' && Character.digit((char)raw[at], 16) < 0) throw new IOException("Invalid H auxiliary value");
                at++;
            }
            if (at == raw.length || (type == 'H' && (at - start) % 2 != 0)) throw new IOException("Unterminated or odd-length auxiliary string");
            at++;
        } else if (type == 'B') {
            if (raw.length - at < 5) throw new IOException("Truncated auxiliary array");
            int subtype = raw[at++] & 255;
            int n = i32(raw, at);
            at += 4;
            int size = switch (subtype) {
            case 'c', 'C' -> yield 1;
            case 's', 'S' -> yield 2;
            case 'i', 'I', 'f' -> yield 4;
            default -> yield 0;
            };
            long end = (long)at + (long)n * size;
            if (size == 0 || n < 0 || end > raw.length) throw new IOException("Invalid auxiliary array bounds");
            at = (int)end;
        } else throw new IOException("Unsupported auxiliary type: " + type);
    }
}

