Row next() throws IOException {
    if (ended) return null;
    try {
        long begin = in.virtualOffset();
        int first = in.read();
        if (first < 0) {
            ended = true;
            logicalEnd = begin;
            observer.boundary(begin);
            return null;
        }
        byte[] sz = {(byte)first, 0, 0, 0};
        System.arraycopy(exact(in, 3), 0, sz, 1, 3);
        int count = i32(sz, 0);
        if (count < 32 || count > limits.recordBytes() || records >= limits.records()) throw new IOException("BAM record size/count exceeds bounds");
        byte[] raw = exact(in, count);
        int ref = i32(raw, 0);
        int pos = i32(raw, 4);
        int flag = u16(raw, 14);
        int nl = raw[8] & 255;
        int nc = u16(raw, 12);
        int seq = i32(raw, 16);
        int mate = i32(raw, 20);
        int matePos = i32(raw, 24);
        if (ref < -1 || ref >= nr || pos < -1 || mate < -1 || mate >= nr || matePos < -1 || seq < 0 || nl < 2) throw new IOException("Invalid BAM core fields");
