        if (end > raw.length) throw new IOException("BAM sequence/CIGAR/quality bounds exceed the record");
        if (raw[32 + nl - 1] != 0) throw new IOException("Read name lacks NUL termination");
        for (int j = 32; j < 32 + nl - 1; j++) if ((raw[j] & 255) < 33 || (raw[j] & 255) > 126 || raw[j] == '@') throw new IOException("Require a standard printable ASCII BAM read name");
        String name = new String(raw, 32, nl - 1, StandardCharsets.US_ASCII);
        int referenceSpan = 0;
        int querySpan = 0;
        int leftClip = 0;
        int rightClip = 0;
        boolean clipping = true;
        for (int j = 0; j < nc; j++) {
            int op = i32(raw, 32 + nl + 4 * j);
            int code = op & 15;
            int length = op >>> 4;
            if (code > 8 || length == 0) throw new IOException("Unsupported or zero-length CIGAR operation");
            if (code == 0 || code == 2 || code == 3 || code == 7 || code == 8) referenceSpan = Math.addExact(referenceSpan, length);
            if (code == 0 || code == 1 || code == 4 || code == 7 || code == 8) querySpan = Math.addExact(querySpan, length);
            if (clipping && (code == 4 || code == 5)) leftClip = Math.addExact(leftClip, length); else clipping = false;
        }
        for (int j = nc - 1; j >= 0; j--) {
            int op = i32(raw, 32 + nl + 4 * j);
            int code = op & 15;
            if (code != 4 && code != 5) break;
            rightClip = Math.addExact(rightClip, op >>> 4);
        }
        if (nc > 0 && querySpan != seq) throw new IOException("CIGAR query length differs from sequence length");
        if ((flag & 4) == 0 && (ref < 0 || pos < 0 || nc == 0 || referenceSpan < 1 || (long)pos + referenceSpan > lengths.get(ref))) throw new IOException("Mapped alignment is outside its exact reference geometry");
        if (ref < 0 || pos < 0) unplaced = true; else {
            if (unplaced || ref < previousRef || (ref == previousRef && pos < previousPos)) throw new IOException("BAM records are not in their declared coordinate order");
            previousRef = ref;
            previousPos = pos;
        }
        long score = 0;
        int qualities = 32 + nl + 4 * nc + (seq + 1) / 2;
        for (int j = 0; j < seq; j++) {
            int q = raw[qualities + j] & 255;
            if (q > 93 && q != 255) throw new IOException("Invalid raw base-quality byte");
            if (q >= 15) score += q;
        }
        aux(raw, (int)end);
        boolean eligible = ref >= 0 && (flag & (4 | 256 | 2048)) == 0;
        int five = (flag & 16) == 0 ? pos - leftClip : pos + referenceSpan + rightClip;
        if ((ref < 0) != (pos < 0)) throw new IOException("BAI audit requires reference and position to be both present or both absent; partial coordinates are not repaired");
        int endPosition = ref < 0 ? -1 : Math.toIntExact((long)pos + Math.max(1, (flag & 4) == 0 ? referenceSpan : 0));
        if (ref >= 0 && (endPosition > lengths.get(ref) || endPosition > (1 << 29))) throw new IOException("Alignment lies outside its reference or the BAI512-Mbp coordinate range; use a separately qualified appropriate index format");
        long virtualEnd = in.virtualOffset();
        observer.boundary(begin);
        observer.boundary(virtualEnd);
        return new Row(records++, ref, pos, endPosition, flag, begin, virtualEnd);
    } catch (ArithmeticException | IndexOutOfBoundsException e) {
        throw new IOException("Invalid/overflowing BAM structure; no data repaired", e);
    }
}

private static Header parseHeader(String text, List<String> names, List<Integer> lengths) throws IOException {
    /*missing*/ canonical = new ArrayList<String>();
    /*missing*/ programs = new LinkedHashMap<String, Map<String, String>>();
    /*missing*/ observedNames = new ArrayList<String>();
    /*missing*/ groups = new HashSet<String>();
    boolean hd = false;
    String[] lines = text.split("\n", -1);
    for (int row = 0; row < lines.length; row++) {
        String line = lines[row];
        if (line.isEmpty() && row == lines.length - 1) continue;
        if (line.indexOf('\r') >= 0 || line.indexOf('\u0000') >= 0) throw new IOException("Unsupported CR or NUL in the raw SAM header");
        String[] fields = line.split("\t", -1);
        String type = fields[0];
        if (type.equals("@CO")) {
            canonical.add(line);
            continue;
        }
        if (!Set.of("@HD", "@SQ", "@RG", "@PG").contains(type)) throw new IOException("Unsupported SAM header record");
        /*missing*/ tags = new TreeMap<String, String>();
        for (int j = 1; j < fields.length; j++) {
            if (fields[j].length() < 4 || fields[j].charAt(2) != ':' || tags.putIfAbsent(fields[j].substring(0, 2), fields[j].substring(3)) != null) throw new IOException("Invalid or repeated SAM header tag");
        }
        if (type.equals("@HD")) {
            if (hd || !"coordinate".equals(tags.get("SO"))) throw new IOException("Require one coordinate-sort header");
            hd = true;
        }
        if (type.equals("@SQ")) {
            int index = observedNames.size();
            if (index >= names.size() || !names.get(index).equals(tags.get("SN")) || !Integer.toString(lengths.get(index)).equals(tags.get("LN"))) throw new IOException("Complete text/binary reference dictionary differs");
            observedNames.add(tags.get("SN"));
        }
        if (type.equals("@RG") && (tags.get("ID") == null || !groups.add(tags.get("ID")))) throw new IOException("Repeated or absent read-group ID");
        if (type.equals("@PG") && (tags.get("ID") == null || programs.putIfAbsent(tags.get("ID"), Map.copyOf(tags)) != null)) throw new IOException("Repeated or absent program ID");
        canonical.add(canonical(type, tags));
    }
    if (!hd || observedNames.size() != names.size()) throw new IOException("Incomplete coordinate header/reference dictionary");
    canonical.sort(String::compareTo);
    return new Header(List.copyOf(canonical), Map.copyOf(programs));
}

private static int u16(byte[] b, int at) {
    return (b[at] & 255) | ((b[at + 1] & 255) << 8);
}

private static String utf8(byte[] b) throws IOException {
    return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(b)).toString();
}

