    /**
     * Strict BGZF member framing, CRC, ISIZE, bounds and terminal empty member. 
     */
    private static final class Bgzf extends InputStream {
        private final InputStream raw;
        private final long maximum;
        private long decoded;
        private byte[] block = new byte[0];
        private int at;
        private boolean ended;
        
        Bgzf(Path path, long maximum) throws IOException {
            raw = new BufferedInputStream(Files.newInputStream(path));
            this.maximum = maximum;
        }
        
        private boolean next() throws IOException {
            if (ended) return false;
            int first = raw.read();
            if (first < 0) throw new EOFException("Missing terminal BGZF member");
            byte[] h = new byte[12];
            h[0] = (byte)first;
            System.arraycopy(exact(raw, 11), 0, h, 1, 11);
            if ((h[0] & 255) != 31 || (h[1] & 255) != 139 || h[2] != 8 || h[3] != 4) throw new IOException("Require standard BGZF with FEXTRA only");
            int extraLength = u16(h, 10);
            if (extraLength < 6) throw new IOException("BGZF extra fields are incomplete");
            byte[] extra = exact(raw, extraLength);
            int size = -1;
            for (int p = 0; p < extra.length; ) {
                if (extra.length - p < 4) throw new IOException("Truncated BGZF subfield");
                int n = u16(extra, p + 2);
                if (p + 4 + n > extra.length) throw new IOException("Invalid BGZF subfield length");
                if (extra[p] == 'B' && extra[p + 1] == 'C') {
                    if (size != -1 || n != 2) throw new IOException("Repeated/invalid BGZF BC subfield");
                    size = u16(extra, p + 4) + 1;
                }
                p += 4 + n;
            }
            int payload = size - 12 - extraLength - 8;
            if (payload < 2 || size > 65536) throw new IOException("Invalid BGZF block size");
            byte[] compressed = exact(raw, payload);
            byte[] tail = exact(raw, 8);
            long length = Integer.toUnsignedLong(i32(tail, 4));
            if (length > 65536) throw new IOException("BGZF ISIZE exceeds 64 KiB");
            /*missing*/ inflater = new Inflater(true);
            byte[] data = new byte[65537];
            int written = 0;
            try {
                inflater.setInput(compressed);
                while (!inflater.finished() && written < data.length) {
                    int n = inflater.inflate(data, written, data.length - written);
                    if (n == 0 && !inflater.finished()) throw new IOException("Unfinished BGZF deflate data");
                    written += n;
                }
                if (!inflater.finished() || inflater.getRemaining() != 0 || written != length) throw new IOException("BGZF deflate length/remaining data differs");
            } catch (DataFormatException e) {
                throw new IOException("Invalid BGZF deflate data", e);
            } finally {
                inflater.end();
            }
            CRC32 crc = new CRC32();
            crc.update(data, 0, written);
            if (crc.getValue() != Integer.toUnsignedLong(i32(tail, 0))) throw new IOException("BGZF CRC differs");
            if (written == 0) {
                if (size != 28 || raw.read() != -1) throw new IOException("Nonterminal or invalid empty BGZF member");
                ended = true;
                return false;
            }
            decoded += written;
            if (decoded > maximum) throw new IOException("Decoded BAM bytes exceed the declared limit");
            block = Arrays.copyOf(data, written);
            at = 0;
            return true;
        }
        
        @Override
        public int read() throws IOException {
            if (at == block.length && !next()) return -1;
            return block[at++] & 255;
        }
        
        @Override
        public int read(byte[] b, int off, int len) throws IOException {
            java.util.Objects.checkFromIndexSize(off, len, b.length);
            if (len == 0) return 0;
            if (at == block.length && !next()) return -1;
            int n = Math.min(len, block.length - at);
            System.arraycopy(block, at, b, off, n);
            at += n;
            return n;
        }
        
        @Override
        public void close() throws IOException {
            raw.close();
        }
    }
}

