private static List<String> commandIndependentHeader(Header h, String command) throws IOException {
    /*missing*/ result = new ArrayList<>(h.canonical);
    int matches = 0;
    for (/*missing*/ p : h.programs.values()) if (command.equals(p.get("CL"))) {
        String original = canonical("@PG", p);
        /*missing*/ copy = new TreeMap<>(p);
        copy.put("CL", "<EXACT_DECLARED_COMMAND>");
        if (!result.remove(original)) throw new IOException("Program header inventory differs");
        result.add(canonical("@PG", copy));
        matches++;
    }
    if (matches != 1) throw new IOException("Exact execution command must identify one program header");
    result.sort(String::compareTo);
    return result;
}

public static void compareActualRuns(Path earlier, Path replay, String earlierCommand, String replayCommand, Limits limits) throws IOException {
    Bam a = read(earlier, limits);
    Bam b = read(replay, limits);
    if (!Arrays.equals(a.dictionary, b.dictionary) || a.reads.size() != b.reads.size()) throw new IOException("Actual replay dictionary or record count differs");
    for (int i = 0; i < a.reads.size(); i++) if (!Arrays.equals(a.reads.get(i).bytes, b.reads.get(i).bytes)) throw new IOException("Actual original replay record differs at ordinal " + i);
    if (!commandIndependentHeader(a.header, earlierCommand).equals(commandIndependentHeader(b.header, replayCommand))) throw new IOException("Replay header differs beyond the exact declared command paths");
}

