private static void header(Bam input, Bam output, String edition, String command) throws IOException {
    String vn = switch (edition) {
    case "0.6.6" -> yield "0.6.6";
    case "0.8.2" -> yield "1.0";
    default -> throw new IllegalArgumentException("Explicit Sambamba edition must be 0.6.6 or 0.8.2");
    };
    if (command == null || !command.startsWith("markdup ") || command.indexOf('\n') >= 0 || command.indexOf('\r') >= 0) throw new IllegalArgumentException("Supply the exact original markdup command; no line-break paths are supported");
    if (!Arrays.equals(input.dictionary, output.dictionary)) throw new IOException("Complete binary reference dictionary changed");
    /*missing*/ remaining = new ArrayList<>(output.header.canonical);
    for (String line : input.header.canonical) if (!remaining.remove(line)) throw new IOException("Original header values were changed or lost");
    if (remaining.size() != 1 || !remaining.get(0).startsWith("@PG\t")) throw new IOException("Require exactly one added original program record");
    Map<String, String> added = null;
    for (/*missing*/ entry : output.header.programs.entrySet()) if (!input.header.programs.containsKey(entry.getKey())) {
        if (added != null) throw new IOException("Multiple new original program IDs");
        added = entry.getValue();
    }
    if (added == null || !added.get("ID").matches("sambamba(?:[._-][0-9]+)?") || !vn.equals(added.get("VN")) || !command.equals(added.get("CL"))) throw new IOException("Original program ID/version/exact command differs; edition is not inferred from header VN");
    Set<String> keys = input.header.programs.isEmpty() ? Set.of("ID", "VN", "CL") : Set.of("ID", "VN", "CL", "PP");
    if (!added.keySet().equals(keys) || (!input.header.programs.isEmpty() && !input.header.programs.containsKey(added.get("PP")))) throw new IOException("Original program fields or predecessor reference differ");
}

