            if (size == 0 || n < 0 || end > raw.length) throw new IOException("Invalid auxiliary array bounds");
            at = (int)end;
        } else throw new IOException("Unsupported auxiliary type: " + type);
    }
}

private static String canonical(String type, Map<String, String> tags) {
    /*missing*/ b = new StringBuilder(type);
    new TreeMap<>(tags).forEach((k,v)->b.append('\t').append(k).append(':').append(v));
    return b.toString();
}

private static List<String> commandIndependentHeader(Header h, String command) throws IOException {
    /*missing*/ result = new ArrayList<>(h.canonical);
    int matches = 0;
    for (/*missing*/ p : h.programs.values()) if (command.equals(p.get("CL"))) {
        String original = canonical("@PG", p);
        /*missing*/ copy = new TreeMap<>(p);
        copy.put("CL", "<EXACT_DECLARED_COMMAND>");
        if (!result.remove(original)) throw new IOException("Program header inventory differs");
        result.add(canonical("@PG", copy));
        matches++;
    }
    if (matches != 1) throw new IOException("Exact execution command must identify one program header");
    result.sort(String::compareTo);
    return result;
}

public static long compareActualRuns(Path earlier, Path replay, String earlierCommand, String replayCommand, Limits limits) throws IOException {
    try (/*missing*/ a = new Cursor(earlier, limits);
/*missing*/ b = new Cursor(replay, limits);) {
            if (!Arrays.equals(a.dictionary, b.dictionary)) throw new IOException("Actual replay dictionary differs");
            if (!commandIndependentHeader(a.header, earlierCommand).equals(commandIndependentHeader(b.header, replayCommand))) throw new IOException("Replay header differs beyond the exact declared command paths");
            long ordinal = 0;
            while (true) {
                Read x = a.next();
                Read y = b.next();
                if (x == null && y == null) return ordinal;
                if (x == null || y == null) throw new IOException("Actual replay record count differs at ordinal " + ordinal);
                if (!Arrays.equals(x.bytes, y.bytes)) throw new IOException("Actual original replay record differs at ordinal " + ordinal);
                ordinal++;
            }
        }
    }

private static byte[] exact(InputStream in, int n) throws IOException {
    byte[] b = in.readNBytes(n);
    if (b.length != n) throw new EOFException("Truncated BGZF/BAM data");
    return b;
}

private static void header(Cursor input, Cursor output, String edition, String command) throws IOException {
    String vn = switch (edition) {
    case "0.6.6" -> yield "0.6.6";
    case "0.8.2" -> yield "1.0";
    default -> throw new IllegalArgumentException("Explicit Sambamba edition must be 0.6.6 or 0.8.2");
    };
    if (command == null || !command.startsWith("markdup ") || command.indexOf('\n') >= 0 || command.indexOf('\r') >= 0) throw new IllegalArgumentException("Supply the exact original markdup command; no line-break paths are supported");
    if (!Arrays.equals(input.dictionary, output.dictionary)) throw new IOException("Complete binary reference dictionary changed");
    /*missing*/ remaining = new ArrayList<>(output.header.canonical);
    for (String line : input.header.canonical) if (!remaining.remove(line)) throw new IOException("Original header values were changed or lost");
    if (remaining.size() != 1 || !remaining.get(0).startsWith("@PG\t")) throw new IOException("Require exactly one added original program record");
    Map<String, String> added = null;
    for (/*missing*/ entry : output.header.programs.entrySet()) if (!input.header.programs.containsKey(entry.getKey())) {
        if (added != null) throw new IOException("Multiple new original program IDs");
        added = entry.getValue();
    }
    if (added == null || !added.get("ID").matches("sambamba(?:[._-][0-9]+)?") || !vn.equals(added.get("VN")) || !command.equals(added.get("CL"))) throw new IOException("Original program ID/version/exact command differs; edition is not inferred from header VN");
    Set<String> keys = input.header.programs.isEmpty() ? Set.of("ID", "VN", "CL") : Set.of("ID", "VN", "CL", "PP");
    if (!added.keySet().equals(keys) || (!input.header.programs.isEmpty() && !input.header.programs.containsKey(added.get("PP")))) throw new IOException("Original program fields or predecessor reference differ");
}

private static int i32(byte[] b, int at) {
    return ByteBuffer.wrap(b, at, 4).order(ByteOrder.LITTLE_ENDIAN).getInt();
}

