    try (/*missing*/ cursor = new Cursor(input, limits);) {
        while (cursor.next() != null) {
        }
        return new InputSummary(cursor.records, cursor.identity());
    }
}

private static int integer(InputStream in) throws IOException {
    return i32(exact(in, 4), 0);
}

private static byte[] le(int n) {
    return ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN).putInt(n).array();
}

private static Header parseHeader(String text, List<String> names, List<Integer> lengths) throws IOException {
    /*missing*/ canonical = new ArrayList<String>();
    /*missing*/ programs = new LinkedHashMap<String, Map<String, String>>();
    /*missing*/ observedNames = new ArrayList<String>();
    /*missing*/ groups = new HashSet<String>();
    boolean hd = false;
    String[] lines = text.split("\n", -1);
    for (int row = 0; row < lines.length; row++) {
        String line = lines[row];
        if (line.isEmpty() && row == lines.length - 1) continue;
        if (line.indexOf('\r') >= 0 || line.indexOf('\u0000') >= 0) throw new IOException("Unsupported CR or NUL in the raw SAM header");
        String[] fields = line.split("\t", -1);
        String type = fields[0];
        if (type.equals("@CO")) {
            canonical.add(line);
            continue;
        }
        if (!Set.of("@HD", "@SQ", "@RG", "@PG").contains(type)) throw new IOException("Unsupported SAM header record");
        /*missing*/ tags = new TreeMap<String, String>();
        for (int j = 1; j < fields.length; j++) {
            if (fields[j].length() < 4 || fields[j].charAt(2) != ':' || tags.putIfAbsent(fields[j].substring(0, 2), fields[j].substring(3)) != null) throw new IOException("Invalid or repeated SAM header tag");
        }
        if (type.equals("@HD")) {
            if (hd || !"coordinate".equals(tags.get("SO"))) throw new IOException("Require one coordinate-sort header");
            hd = true;
        }
        if (type.equals("@SQ")) {
            int index = observedNames.size();
            if (index >= names.size() || !names.get(index).equals(tags.get("SN")) || !Integer.toString(lengths.get(index)).equals(tags.get("LN"))) throw new IOException("Complete text/binary reference dictionary differs");
            observedNames.add(tags.get("SN"));
        }
        if (type.equals("@RG") && (tags.get("ID") == null || !groups.add(tags.get("ID")))) throw new IOException("Repeated or absent read-group ID");
        if (type.equals("@PG") && (tags.get("ID") == null || programs.putIfAbsent(tags.get("ID"), Map.copyOf(tags)) != null)) throw new IOException("Repeated or absent program ID");
        canonical.add(canonical(type, tags));
    }
    if (!hd || observedNames.size() != names.size()) throw new IOException("Incomplete coordinate header/reference dictionary");
    canonical.sort(String::compareTo);
    return new Header(List.copyOf(canonical), Map.copyOf(programs));
}

private static boolean sameExceptDuplicate(byte[] a, byte[] b) {
    return a.length == b.length && Arrays.equals(a, 0, 15, b, 0, 15) && ((a[15] ^ b[15]) & 251) == 0 && Arrays.equals(a, 16, a.length, b, 16, b.length);
}

private static int u16(byte[] b, int at) {
    return (b[at] & 255) | ((b[at + 1] & 255) << 8);
}

private static String utf8(byte[] b) throws IOException {
    return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(b)).toString();
}

public static long validateInput(Path input, Limits limits) throws IOException {
    return inspectInput(input, limits).records();
}

