package org.jlinalg.cli;

import java.io.IOException;
import java.io.PrintStream;
import java.nio.file.Files;
import java.util.Arrays;

/**
 * Executable, bounded-memory statistical association command line. 
 */
public final class JLinAlgCli {
    
    private JLinAlgCli() {
    }
    
    public static void main(String[] arguments) {
        int status = run(arguments);
        if (status != 0) System.exit(status);
    }
    
    static int run(String[] arguments) {
        return run(arguments, System.out, System.err);
    }
    
    static int run(String[] arguments, PrintStream output, PrintStream errorOutput) {
        try {
            if (arguments.length > 0 && arguments[0].equals("study")) return StudyCli.run(Arrays.copyOfRange(arguments, 1, arguments.length), output, errorOutput);
            if (arguments.length > 0 && arguments[0].equals("gseapy-native")) return GseapyNativeCli.run(Arrays.copyOfRange(arguments, 1, arguments.length), output, errorOutput);
            if (arguments.length > 0 && arguments[0].equals("nextflow-tools")) return NextflowToolsCli.run(Arrays.copyOfRange(arguments, 1, arguments.length), output, errorOutput);
            if (arguments.length > 0 && arguments[0].equals("salmon-tools")) return SalmonToolsCli.run(Arrays.copyOfRange(arguments, 1, arguments.length), output, errorOutput);
            if (arguments.length > 0 && arguments[0].equals("sambamba-tools")) return SambambaStreamingWorkflowCli.run(Arrays.copyOfRange(arguments, 1, arguments.length), output, errorOutput);
            if (arguments.length > 0 && arguments[0].equals("tomtom-tools")) return TomtomToolsCli.run(Arrays.copyOfRange(arguments, 1, arguments.length), output, errorOutput);
            if (arguments.length > 0 && arguments[0].equals("bigwig-tools")) return BigWigToolsCli.run(Arrays.copyOfRange(arguments, 1, arguments.length), output, errorOutput);
            if (arguments.length > 0 && arguments[0].equals("stringtie-tools")) return StringTieToolsCli.run(Arrays.copyOfRange(arguments, 1, arguments.length), output, errorOutput);
            if (arguments.length > 0 && arguments[0].equals("chromvar-tools")) return ChromVarToolsCli.run(Arrays.copyOfRange(arguments, 1, arguments.length), output, errorOutput);
            if (arguments.length > 0 && arguments[0].equals("deseq2-tools")) return Deseq2InferenceCli.run(Arrays.copyOfRange(arguments, 1, arguments.length), output, errorOutput);
            if (arguments.length > 0 && arguments[0].equals("deseq2-normalize")) return Deseq2NormalizationCli.run(Arrays.copyOfRange(arguments, 1, arguments.length), output, errorOutput);
            if (arguments.length > 0 && arguments[0].equals("signac-tools")) return SignacToolsCli.run(Arrays.copyOfRange(arguments, 1, arguments.length), output, errorOutput);
            if (arguments.length > 0 && arguments[0].equals("htseq-tools")) return HtseqToolsCli.run(Arrays.copyOfRange(arguments, 1, arguments.length), output, errorOutput);
            if (arguments.length > 0 && arguments[0].equals("meme-tools")) return MemeToolsCli.run(Arrays.copyOfRange(arguments, 1, arguments.length), output, errorOutput);
            if (arguments.length > 0 && arguments[0].equals("chipseeker-tools")) return ChipSeekerToolsCli.run(Arrays.copyOfRange(arguments, 1, arguments.length), output, errorOutput);
            if (arguments.length > 0 && arguments[0].equals("monocle-tools")) return MonocleToolsCli.run(Arrays.copyOfRange(arguments, 1, arguments.length), output, errorOutput);
            ProjectConfiguration.Resolved config = ProjectConfiguration.resolve(arguments, java.nio.file.Path.of("").toAbsolutePath(), java.nio.file.Path.of(System.getProperty("user.home")));
            arguments = config.arguments();
            if (arguments.length == 1 && arguments[0].equals("config")) {
                output.print(new org.yaml.snakeyaml.Yaml().dump(config.provenance()));
                return 0;
            }
            java.nio.file.Path record = null;
            boolean auditConfig = !((java.util.List<?>)config.provenance().get("sources")).isEmpty() || arguments.length > 0 && java.util.Set.of("single-cell", "spatial", "network", "variant-db", "variant-annotate", "variant-consequence", "variant-score").contains(arguments[0]);
            if (auditConfig && !Arrays.asList(arguments).contains("--help")) {
                for (int i = 0; i + 1 < arguments.length; i++) if (arguments[i].equals("--out")) record = java.nio.file.Path.of(arguments[i + 1] + ".config.yaml");
            }
            if (record != null && Files.exists(record) && !Arrays.asList(arguments).contains("--overwrite")) throw new IOException("Configuration output already exists: " + record);
            if (record != null && Files.exists(record)) for (Object source : (java.util.List<?>)config.provenance().get("sources")) {
                String path = String.valueOf(((java.util.Map<?, ?>)source).get("path"));
                if (Files.isSameFile(record, java.nio.file.Path.of(path))) throw new IOException("Configuration output aliases a source configuration");
            }
            if (record != null) for (String value : arguments) {
                if (value.startsWith("--")) continue;
                try {
                    if (Files.exists(record) && Files.exists(java.nio.file.Path.of(value)) && Files.isSameFile(record, java.nio.file.Path.of(value))) throw new IOException("Configuration output aliases an input");
                } catch (java.nio.file.InvalidPathException ignored) {
                }
            }
            int status = runConfigured(arguments, output, errorOutput);
            if (status == 0 && record != null) {
                Files.createDirectories(record.toAbsolutePath().getParent());
                Files.writeString(record, new org.yaml.snakeyaml.Yaml().dump(config.provenance()));
            }
            return status;
        } catch (IOException | RuntimeException exception) {
            errorOutput.println("jlinalg: " + exception.getMessage());
            return 2;
        }
    }
    
