    case "ldd-setpriv" -> yield List.of("/usr/bin/ldd", "/usr/bin/setpriv");
    case "ldd-prlimit" -> yield List.of("/usr/bin/ldd", "/usr/bin/prlimit");
    case "ldd-bash" -> yield List.of("/usr/bin/ldd", "/usr/bin/bash");
    case "mark" -> yield command(binary, c, historical, false);
    case "remove" -> yield command(binary, c, historical, true);
    default -> throw new IllegalArgumentException("Unknown recorded phase");
    };
}

