        }
        if (capture.getProperty("kind").equals("analysis")) {
            if (!capture.getProperty("parent_bundle").isEmpty() || !capture.getProperty("parent_marker_sha256").isEmpty() || !capture.getProperty("capture_source").equals(capture.getProperty("bam_resolved"))) throw new IOException("Original-run capture provenance differs");
