        return switch (phase) {
        case "version" -> yield List.of(binary.toString(), "--version");
        case "ldd-source" -> yield List.of("/usr/bin/ldd", binary.toString());
        case "ldd-setpriv" -> yield List.of("/usr/bin/ldd", "/usr/bin/setpriv");
        case "ldd-prlimit" -> yield List.of("/usr/bin/ldd", "/usr/bin/prlimit");
        case "ldd-bash" -> yield List.of("/usr/bin/ldd", "/usr/bin/bash");
        case "mark" -> yield command(binary, c, historical, false);
        case "remove" -> yield command(binary, c, historical, true);
        default -> throw new IllegalArgumentException("Unknown recorded phase");
        };
    }
    
    static void process(Path root, String phase, Config c, Properties capture) throws Exception {
        boolean analysis = phase.equals("mark") || phase.equals("remove");
        long wall = analysis ? c.number("wall_ms") : 10000;
        long address = analysis ? c.addressBytes() : 512L << 20;
        List<String> source = sourceCommand(phase, c, capture);
        List<String> launch = new ArrayList<>(List.of("/usr/bin/setpriv", "--pdeathsig", "KILL", "/usr/bin/prlimit", "--as=" + address, "--"));
        launch.addAll(source);
        Properties pid = load(root.resolve(phase + ".pid.properties"));
        Set<String> expected = new TreeSet<>(Set.of("pid", "parent_pid", "start_instant", "parent_death_signal_requested", "address_space_limit_method", "source_argc", "launch_argc", "linux_start_ticks"));
