        Properties marker = new Properties();
        marker.setProperty("profile", PROFILE);
        marker.setProperty("status", "completed");
        marker.setProperty("kind", capture.getProperty("kind"));
        marker.setProperty("selected_bam", selected(c));
        marker.setProperty("bai_independently_qualified", "false");
        marker.setProperty("new_catalog_credit", "0");
        inventory.members().forEach((n,h)->marker.setProperty("member." + n, h));
        byte[] raw = bytes(marker);
        if (inventory.entries() + 1 > c.number("max_files") || inventory.bytes() + raw.length > c.workBytes()) throw new IOException("Prospective completion receipt exceeds the declared workspace capacity");
        write(root.resolve("COMPLETED.properties"), raw);
