            /*missing*/ effective = new LinkedHashMap<>(original.values());
            effective.put("bam", "input.bam");
            effective.put("sambamba", executable.toString());
            c = config(properties(effective));
            capture = new Properties();
            capture.setProperty("profile", PROFILE);
            capture.setProperty("kind", "analysis");
            capture.setProperty("request_path_requested", options.get("request"));
            capture.setProperty("request_directory", requestDir.toString());
            capture.setProperty("request_sha256", sha(raw));
            capture.setProperty("bam_requested", original.get("bam"));
            capture.setProperty("bam_request_absolute", requestedBam.toString());
            capture.setProperty("bam_resolved", source.toString());
            capture.setProperty("binary_requested", original.get("sambamba"));
            capture.setProperty("binary_request_absolute", requestedBinary.toString());
            capture.setProperty("binary_resolved", executable.toString());
            capture.setProperty("input_sha256", inputHash);
            capture.setProperty("capture_source", source.toString());
