        SambambaWorkflowRuntime.verify(runtime);
        store(owned.resolve("runtime-after.properties"), runtime);
        if (old != null) {
            for (boolean remove : c.remove() ? List.of(false, true) : List.of(false)) {
                String phase = remove ? "remove" : "mark";
                String name = remove ? "deduplicated.bam" : "marked.bam";
