        int code = failure instanceof Prerequisite ? 3 : 2;
        String label = code == 3 ? "SKIP3_SAMBAMBA_PREREQUISITE_UNAVAILABLE" : "FAIL2_SAMBAMBA_ANALYSIS_UNADMITTED";
        if (owned != null) try {
            Path marker = owned.resolve("COMPLETED.properties");
            if (Files.exists(marker)) Files.move(marker, owned.resolve("COMPLETION-INVALIDATED-" + UUID.randomUUID() + ".properties"));
            write(owned.resolve("FAILURE.txt"), label + "\n" + failure.getClass().getName() + ": " + failure.getMessage() + "\nNo accepted result. Retain provisional files and original bundles. Supply the named permitted prerequisite or correct the cause; retry NEW output. Read WARNINGS.md and phase consoles.\n");
        } catch (Throwable recording) {
            error.println("FAIL2_FAILURE_RECORDING_UNAVAILABLE " + recording);
            code = 2;
        }
        error.println(label + ": " + failure);
        error.println("No accepted result. Read WARNINGS.md/FAILURE.txt and phase consoles when present. Supply the named permitted prerequisite or correct the cause, preserve originals, and retry NEW output; skip dependent analysis when unavailable.");
        return code;
    }
