private static void integer(Properties p, String key, int min, int max) {
    String raw = p.getProperty(key);
    int n;
    try {
        n = Integer.parseInt(raw);
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("Use a canonical integer for " + key, e);
    }
    if (!Integer.toString(n).equals(raw) || n < min || n > max) throw new IllegalArgumentException(key + " must be a canonical integer in " + min + ".." + max);
}

static Path intendedNew(Path requested) throws IOException {
    if (requested.getParent() == null || Files.exists(requested, LinkOption.NOFOLLOW_LINKS)) throw new IOException("Choose a NEW output directory; existing paths are preserved");
    Path ancestor = requested;
    /*missing*/ missing = new ArrayList<Path>();
    while (!Files.exists(ancestor, LinkOption.NOFOLLOW_LINKS)) {
        missing.add(ancestor.getFileName());
        ancestor = ancestor.getParent();
        if (ancestor == null) throw new IOException("Output has no existing absolute ancestor");
    }
    Path result = ancestor.toRealPath();
    for (int i = missing.size() - 1; i >= 0; i--) result = result.resolve(missing.get(i));
    return result.normalize();
}

static Inventory inventory(Path root, Config config, boolean hashes) throws Exception {
    Map<String, String> members = new TreeMap<>();
    long bytes = 0;
    int count = 0;
    try (/*missing*/ walk = Files.walk(root);) {
        for (/*missing*/ iterator = walk.iterator(); iterator.hasNext(); ) {
            Path p = iterator.next();
            if (p.equals(root)) continue;
            if (!hashes && !Files.exists(p, LinkOption.NOFOLLOW_LINKS)) continue;
            if (++count > config.number("max_files")) throw new IOException("Workspace file/directory count exceeds max_files");
            if (Files.isSymbolicLink(p)) throw new IOException("Workspace contains an unqualified symbolic link: " + p);
            String name = root.relativize(p).toString().replace(java.io.File.separatorChar, '/');
            if (Files.isDirectory(p, LinkOption.NOFOLLOW_LINKS)) members.put(name, "DIRECTORY"); else if (Files.isRegularFile(p, LinkOption.NOFOLLOW_LINKS)) {
                long size;
                try {
                    size = Files.size(p);
                } catch (java.nio.file.NoSuchFileException e) {
                    if (!hashes) continue;
                    throw e;
                }
                bytes = Math.addExact(bytes, size);
                if (bytes > config.workBytes()) throw new IOException("Workspace bytes exceed work_mb; the analysis is not admitted");
                members.put(name, hashes ? sha(p) : "FILE");
            } else if (hashes || Files.exists(p, LinkOption.NOFOLLOW_LINKS)) throw new IOException("Workspace member is not a regular file/directory: " + name);
        }
    }
    return new Inventory(members, bytes, count);
}

static void linux() throws Prerequisite {
    if (!System.getProperty("os.name").equals("Linux") || !Set.of("amd64", "x86_64").contains(System.getProperty("os.arch"))) throw new Prerequisite("Run this profile in a permitted Linux x86-64 JVM, including Java inside your selected WSL distribution. The exact Linux releases cannot execute in a native Windows JVM.");
    for (String helper : List.of("/usr/bin/setpriv", "/usr/bin/prlimit", "/usr/bin/ldd")) if (!Files.isExecutable(Path.of(helper))) throw new Prerequisite("Required Linux helper unavailable: " + helper + ". Supply a permitted util-linux/glibc runtime and retry a NEW directory; skip dependent analysis.");
}

static Properties load(Path path) throws IOException {
    if (!Files.isRegularFile(path, LinkOption.NOFOLLOW_LINKS) || Files.size(path) > 1048576) throw new IOException("Require a regular properties file <=1 MiB: " + path);
    return parse(Files.readString(path, StandardCharsets.UTF_8));
}

static Properties parse(String text) throws IOException {
    Properties p = new UniqueProperties();
    p.load(new StringReader(text));
    return p;
}

static void scientificCoherence(Config original, Config effective) {
    for (String key : KEYS) if (!Set.of("bam", "sambamba").contains(key) && !original.get(key).equals(effective.get(key))) throw new IllegalArgumentException("Original/effective request contradiction: " + key);
    if (!effective.get("bam").equals("input.bam") || !Path.of(effective.get("sambamba")).isAbsolute()) throw new IllegalArgumentException("Only the recorded captured input and absolute original binary may be relocated");
}

static String sha(Path path) throws Exception {
    return sha(path, Long.MAX_VALUE);
}

static String sha(Path path, long maximum) throws Exception {
    MessageDigest digest = MessageDigest.getInstance("SHA-256");
    try (/*missing*/ in = Files.newInputStream(path);) {
        byte[] b = new byte[65536];
        long size = 0;
        for (int n; (n = in.read(b)) >= 0; ) if (n > 0) {
            size = Math.addExact(size, n);
            if (size > maximum) throw new IOException("File grew beyond its admitted byte bound: " + path);
            digest.update(b, 0, n);
        }
    }
    return HexFormat.of().formatHex(digest.digest());
}

static String sha(byte[] raw) throws Exception {
    return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw));
}

static void store(Path path, Properties p) throws IOException {
    write(path, bytes(p));
