        for (String line : Files.readAllLines(Path.of("/proc", Long.toString(p.pid()), "status"))) if (line.startsWith("VmRSS:")) return Long.parseLong(line.substring(6).strip().split("\\s+")[0]) * 1024;
        return 0;
    } catch (IOException e) {
        if (p.isAlive() && running(p.pid())) throw new IOException("Cannot observe owned process RSS", e);
        return 0;
    }
}

private static boolean running(long pid) {
    try {
        String text = Files.readString(Path.of("/proc", Long.toString(pid), "stat"));
        int end = text.lastIndexOf(')');
        return end >= 0 && text.charAt(end + 2) != 'Z';
    } catch (IOException | IndexOutOfBoundsException e) {
        return false;
    }
}

private static Properties startRecord(Process p, List<String> source, List<String> launch) {
    Properties record = new Properties();
    record.setProperty("pid", Long.toString(p.pid()));
    record.setProperty("parent_pid", Long.toString(ProcessHandle.current().pid()));
    record.setProperty("start_instant", p.info().startInstant().map(Instant::toString).orElse("exited-before-observation"));
    record.setProperty("parent_death_signal_requested", "KILL");
    record.setProperty("address_space_limit_method", "prlimit_RLIMIT_AS");
    record.setProperty("source_argc", Integer.toString(source.size()));
    for (int i = 0; i < source.size(); i++) record.setProperty("source_argv." + i, source.get(i));
    record.setProperty("launch_argc", Integer.toString(launch.size()));
    for (int i = 0; i < launch.size(); i++) record.setProperty("launch_argv." + i, launch.get(i));
    try {
        String text = Files.readString(Path.of("/proc", Long.toString(p.pid()), "stat"));
        record.setProperty("linux_start_ticks", text.substring(text.lastIndexOf(')') + 2).split("\\s+")[19]);
    } catch (IOException | IndexOutOfBoundsException e) {
        record.setProperty("linux_start_ticks", "exited-before-observation");
    }
    return record;
}

